package org.transittr;
import android.content.*;import android.graphics.*;import android.net.Uri;import java.io.*;import java.text.*;import java.util.*;
/** Compact share card; only values already visible in the query are rendered. */
public final class ShareCard {
 private static String clipped(Paint p,String text,float max){if(text==null)return "";while(text.length()>1&&p.measureText(text)>max)text=text.substring(0,text.length()-1);return text;}
 public static Uri create(Context context,String city,String stop,String line,JourneyData.Snapshot snapshot)throws IOException{int count=snapshot==null?0:Math.min(4,snapshot.rows.size()),height=310+Math.max(1,count)*58;Bitmap bitmap=Bitmap.createBitmap(600,height,Bitmap.Config.RGB_565);try{Canvas c=new Canvas(bitmap);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);c.drawColor(0xfff6f7f4);p.setColor(0xff15211c);p.setTextSize(26);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("TRANSIT TR",30,50,p);p.setTextSize(20);p.setTypeface(Typeface.DEFAULT);p.setColor(0xff4e6157);c.drawText(clipped(p,city+" · Durak "+stop+(line.length()>0?" · Hat "+line:""),540),30,92,p);p.setColor(0xff1c2e25);p.setTextSize(23);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("Durağa varış",30,151,p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(18);p.setColor(0xff55665c);if(snapshot==null||count==0)c.drawText("Henüz varış sonucu yok",30,211,p);else for(int i=0;i<count;i++){JourneyData.Vehicle v=snapshot.rows.get(i);int y=205+i*58;p.setColor(0xff11664c);p.setTextSize(21);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(clipped(p,v.line,90),30,y,p);p.setTypeface(Typeface.DEFAULT);p.setColor(0xff26392e);p.setTextSize(16);c.drawText(clipped(p,v.name,300),128,y,p);String eta=v.eta.length()>0?v.eta:"—";p.setTextSize(21);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(eta,570-p.measureText(eta),y,p);p.setTypeface(Typeface.DEFAULT);p.setColor(0xffdce5de);c.drawLine(30,y+20,570,y+20,p);}p.setColor(0xff596b60);p.setTextSize(15);String date="";if(snapshot!=null){SimpleDateFormat f=new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.US);f.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));date="Son alınma: "+f.format(new Date(snapshot.receivedAt));}c.drawText(date,30,height-65,p);c.drawText("Kaynak verileri ve tahminler değişebilir.",30,height-35,p);ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,bytes))throw new IOException("Görsel oluşturulamadı");File target=new File(new File(context.getCacheDir(),"share"),"query.png");if(!StorageBudget.cache(context,target,bytes.toByteArray(),false))throw new IOException("Önbellekte yeterli yer yok");return Uri.parse("content://"+context.getPackageName()+".share/query.png");}finally{bitmap.recycle();}}
}
